   106	      setConfig((currentConfig) => {
   107	        const nextConfig = DashKit.setItem({
   108	          item: {
   109	            type: dropProps.dragProps.type as WidgetType,
   110	            namespace: 'default',
   111	            data: getWidgetData(dropProps.dragProps.type as WidgetType),
   112	          },
   113	          config: currentConfig,
   114	        });
   115	
   116	        return {
   117	          ...nextConfig,
   118	          layout: nextConfig.layout.map((layoutItem) => {
   119	            const matchingLayout = dropProps.newLayout.find((newLayout) => newLayout.i === layoutItem.i);
   120	
   121	            return matchingLayout ?? layoutItem;
   122	          }),
   123	        } as DashKitProps['config'];
   124	      });
   125	      dropProps.commit();
   126	    },
   127	    [],
   128	  );
   129	
   130	  return (
   131	    <Flex direction="column" gap={4}>
   132	      <Flex justifyContent="space-between" alignItems="center" gap={3}>
   133	        <Box>
   134	          <GravityText variant="header-2">Dashboard</GravityText>
   135	          <GravityText color="secondary">Arrange widgets freely on the grid</GravityText>
   136	        </Box>
   137	        <SegmentedRadioGroup value={editMode ? 'edit' : 'view'} onUpdate={(value) => setEditMode(value === 'edit')}>
   138	          <SegmentedRadioGroup.Option value="view">View</SegmentedRadioGroup.Option>
   139	          <SegmentedRadioGroup.Option value="edit">Edit</SegmentedRadioGroup.Option>
   140	        </SegmentedRadioGroup>
   141	      </Flex>
   142	
   143	      <Flex gap={2} alignItems="center">
   144	        <Plus />
   145	        <GravityText>Palette</GravityText>
   146	        {widgetCatalog.map((widget) => (
   147	          <Flex key={widget.type} gap={1} alignItems="center">
   148	            {widget.icon}
   149	            <GravityText>{widget.title}</GravityText>
   150	          </Flex>
   151	        ))}
   152	      </Flex>
   153	
   154	      <DashKitDnDWrapper
   155	        children={
   156	          <>
   157	          <DashKit
   158	            key="dashboard"
   159	            config={config}
   160	            editMode={editMode}
   161	            settings={widgetSettings}
   162	            context={context}
   163	            itemsStateAndParams={itemsStateAndParams}
   164	            onItemEdit={() => setEditMode(true)}
   165	            onChange={({ config: nextConfig, itemsStateAndParams: nextStateAndParams }) => {
   166	              setConfig(nextConfig);
   167	              setItemsStateAndParams(nextStateAndParams);
   168	            }}
   169	            onDrop={handleDrop}
   170	          />
   171	          <ActionPanel key="palette" items={actionPanelItems} />
   172	          </>
   173	        }
   174	      />
   175	    </Flex>
   176	  );
   177	}

